"Agent 高级设置": "Agent Advanced Settings",
"Agent 高级设置:扇出型 Agent 并发额度、运行/无输出超时、跨轮对话记忆额度、自动重跑次数上限、重跑等待确认时间、思考深度": "Agent advanced settings: fan-out agent concurrency, run / no-output timeouts, cross-turn conversation memory budget, auto-retry cap, retry-confirmation wait time, thinking effort",
"重跑等待确认(秒)": "Retry confirmation wait (s)",
"重跑等待确认需为 {min}-{max} 的整数(秒)": "Retry confirmation wait must be an integer between {min} and {max} (seconds)",
"重跑类确认弹窗(「是否重跑?」等)的等待时长,默认 60 秒:倒计时结束无人答复即自动采用默认选项(通常为「重跑」),流水线不会因等人而卡住。调大可给自己留更多裁决时间,代价是无人值守时流水线在弹窗上等得更久;Agent 显式指定的更短等待仍有效,但不能超过本值。签字类弹窗(H 门人工签字)永不倒计时、永不自动确认,不受本项影响。全局设置,保存后对后续发起的确认生效。": "How long a retry-type confirmation popup ('Retry?' etc.) waits, default 60 seconds: when the countdown ends with no answer, the default option (usually 'Retry') is applied automatically, so the pipeline never stalls waiting for a person. Raise it to give yourself more time to decide, at the cost of the pipeline waiting longer on the popup when unattended; a shorter wait explicitly requested by an agent still applies, but can never exceed this value. Sign-off popups (H-gate manual sign-off) never count down and never auto-confirm, so they are unaffected. Global setting; takes effect for confirmations raised after saving.",
"⚙️ Agent 高级设置": "⚙️ Agent Advanced Settings",
"重跑次数": "Retry count",
"Agent 自动重跑/重 roll 的次数上限,默认 0:验收评分、QA 审核或机检不过时,总制片带意见自动退回重做;视频/图像生成机检不达标时自动重 roll。同一任务累计达到该次数仍不过就升级用户裁决,不再自行重试;填 0 则完全不自动重跑,首次不过即升级人工。全局设置,通过运行提示词注入所有 Agent,覆盖流程文档里写死的「最多 3 次」,保存后对后续启动的工单生效。": "Cap on how many times agents automatically rerun / reroll, default 0: when acceptance scoring, QA review or machine checks fail, the Producer automatically sends the work back with feedback for redoing; when video/image generation fails machine checks it automatically rerolls. Once the same task has hit this count and still fails, it is escalated to the user for a decision instead of retrying further; 0 disables auto-retry entirely (the first failure escalates to a human). Global setting, injected into every agent via the runtime prompt and overriding the “at most 3 times” hard-coded in the workflow docs; applies to runs started after saving.",
"重跑次数需为 0-{max} 的整数(0=不自动重跑)": "Retry count must be an integer between 0 and {max} (0 = no auto-retry)",
"轮次上限": "Turn limit",
"单个工单内引擎的对话轮次上限,默认 250:仅对 claude 与 grok 引擎生效(headless 的 --max-turns 参数,不传则不限,这里主动设闸防失控循环);codex/pi/opencode 引擎无此参数不受影响,deepagents 走框架自身的递归上限。撞上限时引擎会被直接切断且无法续跑,回执只显示退出码 1,已落盘的产物保留但核验与回执缺失——大批量工位(逐组选片、批量切片)一单几十组时 100 轮远远不够,如仍撞限优先调小派单批宽、其次上调本值。全局设置,保存后对后续启动的工单生效。": "Cap on engine conversation turns within a single work order, default 250: only affects the claude and grok engines (the headless --max-turns flag; omitting it means unlimited — this gate exists to stop runaway loops). The codex/pi/opencode engines have no such flag and are unaffected; deepagents uses its framework's own recursion limit. When the cap is hit the engine is cut off with no way to resume — the receipt only shows exit code 1; artifacts already written to disk survive but verification and the receipt are missing. For high-volume stations (per-group curation, batch cutting) a single order covering dozens of groups makes 100 turns far too few; if you still hit the cap, first shrink the dispatch batch size, then raise this value. Global setting; applies to runs started after saving.",
"轮次上限需为 {min}-{max} 的整数": "Turn limit must be an integer between {min} and {max}",
"思考深度": "Thinking effort",
"引擎默认": "Engine default",
"思考深度(Thinking Effort)统一设置,默认「引擎默认」:派单时按当前引擎翻译成各自的推理强度参数——claude → --effort,codex → model_reasoning_effort(无 max,按 xhigh),pi → --thinking,opencode → --variant(模型没有该档位时被忽略),grok → --reasoning-effort(无 max,按 xhigh),deepagents → reasoning_effort(仅云端/OpenRouter 渠道,本地模型不传);kimi CLI 无对应参数,不受影响。越深越稳但越慢、token 消耗越高;「引擎默认」不传任何参数,沿用各引擎自身配置(如 ~/.claude/settings.json 的 effortLevel、~/.codex/config.toml 的 model_reasoning_effort)。全局设置,对所有 Agent 生效,保存后对后续启动的工单生效。": "Unified Thinking Effort setting, default \"Engine default\": at dispatch it is translated into each engine's reasoning-strength parameter — claude → --effort, codex → model_reasoning_effort (no max; mapped to xhigh), pi → --thinking, opencode → --variant (ignored when the model has no such variant), grok → --reasoning-effort (no max; mapped to xhigh), deepagents → reasoning_effort (cloud/OpenRouter channels only; not sent to local models); the kimi CLI has no such parameter and is unaffected. Deeper is more reliable but slower and costs more tokens; \"Engine default\" sends nothing and keeps each engine's own configuration (e.g. effortLevel in ~/.claude/settings.json, model_reasoning_effort in ~/.codex/config.toml). Global setting, applies to all agents, effective for runs started after saving.",
