",自动运行每次唤醒总制片时都随消息附带,总制片会话重开也不丢失;适合放长期约束,建议写成条件式(如「在 ep01-ep10 剧本全部完成前,不派设定类工单」),留空则不附带": ", attached to the message every time auto-run wakes the Producer, so it survives even after the Producer's session is reopened; suited to long-term constraints, best phrased conditionally (e.g. 「until all ep01-ep10 scripts are finished, do not dispatch design-type work orders」); leave empty to attach nothing",
