"闲置时间(min)": "Idle interval (min)",
"闲置时间:每隔该时长巡检一次,流水线空闲(无任务在跑、无待确认项)才发送状态检查消息,默认 5 分钟。阈值:总制片生效引擎(claude/codex)的 5 小时窗口会话用量达到该值时,本轮不发送;用量读取不到时放行。均为全局设置,对所有项目生效(开关在运行面板 🤖 按钮,按项目独立)": "Idle interval: a patrol runs once per interval, and the status-check message is sent only when the pipeline is idle (no tasks running, nothing awaiting confirmation); default 5 minutes. Threshold: when the 5-hour-window session usage of the Producer's active engine (claude/codex) reaches this value, this round is skipped; if usage cannot be read, it is allowed through. Both are global settings applying to all projects (the toggle is the 🤖 button in the run panel, per project)",
"闲置时间需为 1-720 的整数(分钟)": "Idle interval must be an integer between 1 and 720 (minutes)",
