"默认关。开启后控制台每个 Agent 面板显示「SOUL.md」按钮,可查看该 Agent 的身份原文;不影响采集与导出": "Off by default. When on, every Agent panel in the console shows a \"SOUL.md\" button to view that Agent's identity text; collection and export are unaffected",
"查看该 Agent 的 SOUL.md 原文(Debug 模式,设置→高级→诊断数据)": "View this Agent's SOUL.md source (Debug mode, Settings → Advanced → Diagnostic Data)",
"开启时在运行结束与生成结束处按字段白名单记录结构化事件(引擎/Agent/渠道/状态/时长/脱敏后的错误模板),只写入本机 data/.videoagents/telemetry/,不含提示词、项目内容、文件路径与 API Key,永不自动上传。「导出诊断包」生成一个 zip(事件 + 环境摘要 + 下方勾选的经验卡),由你自行提交给开发者(如 GitHub issue 附件),用于改进产品。": "When enabled, structured events are recorded at run/generation completion using a field whitelist (engine/agent/provider/status/duration/sanitized error template), written only to local data/.videoagents/telemetry/ — no prompts, project content, file paths or API keys, and never uploaded automatically. \"Export diagnostic bundle\" creates a zip (events + environment summary + the lesson cards checked below) that you submit to the developers yourself (e.g. as a GitHub issue attachment) to help improve the product.",
