"点击「启用」后,可在下方管理已入库的素材;人物预览页每张形象图会出现「入库」按钮,分镜重出时已入库(Active)的参考图自动以资产 URI(asset://素材ID)提交。": "After clicking Enable, manage registered assets below; every character image on the Character Preview page gets a Register button, and when a group is regenerated, registered (Active) reference images are submitted automatically as asset URIs (asset://asset-ID).",
"注意:上传入库为异步审核(Processing → Active/Failed),仅 Active 状态的素材可用于视频生成;素材按方舟「项目」隔离,下方 ProjectName 须与「生成模型」页视频生成所用方舟 API Key 所属项目一致(默认 default)。": "Note: registration is reviewed asynchronously (Processing → Active/Failed); only Active assets can be used for video generation. Assets are isolated by Ark project — ProjectName below must match the project of the Ark API Key used for video generation on the Generation Models page (default: default).",
"🔑 密钥与开关": "🔑 Credentials & Toggle",
"Access Key / Secret Key 留空时,自动使用「⚙️ 设置 → 文件托管 → 火山引擎 TOS」已配置的 AK/SK(或环境变量 TOS_ACCESS_KEY/TOS_SECRET_KEY)。": "If Access Key / Secret Key are left blank, the AK/SK configured under ⚙️ Settings → File Hosting → Volcano TOS (or env vars TOS_ACCESS_KEY/TOS_SECRET_KEY) are used automatically.",
