"视频提示词技能:Prompt 工程师写组级视频提示词时必须套用的官方提示词技能。自动=按真正跑视频生成的模型解析(Seedance 2.5→sd25-pe,Seedance 2.0 系列→sd20-pe,MiniMax H3→h3-pe,Wan 3.0→wan3-pe);解析不到时可手选或跳过。H3A 分镜签字时会再次确认并冻结": "Video prompt skill: the official prompt-writing skill the Prompt Engineer must apply when writing group-level video prompts. Auto = resolved from the model that actually runs video generation (Seedance 2.5→sd25-pe, Seedance 2.0 family→sd20-pe, MiniMax H3→h3-pe, Wan 3.0→wan3-pe); pick one manually or skip when nothing matches. Re-confirmed and frozen at the H3A storyboard sign-off",
