"Qwen Image 3(Fal 托管;中英提示词,参考图 ≤3,支持负面提示词)": "Qwen Image 3 (hosted on Fal; Chinese/English prompts, up to 3 reference images, negative prompt supported)",
"HunyuanImage 3.0(Fal 托管;仅文生图,支持负面提示词)": "HunyuanImage 3.0 (hosted on Fal; text-to-image only, negative prompt supported)",
"Fal 图像生成 API(queue.fal.run 异步队列,托管 Seedream、Nano Banana、GPT Image、FLUX.2、Qwen Image 等端点);模型 ID 填家族前缀,无参考图走文生图端点、有参考图自动切 edit 端点,「自定义…」也可填完整端点 ID;尺寸/参考图上限/seed 按模型映射;Key 与视频段 Fal 共用(任一处填写即可),在": "Fal image generation API (queue.fal.run async queue hosting Seedream, Nano Banana, GPT Image, FLUX.2, Qwen Image and more); the model ID is the family prefix — the text-to-image endpoint is used without references and the edit endpoint is chosen automatically when references are given; \"Custom…\" also accepts a full endpoint ID; size / reference caps / seed are mapped per model; the key is shared with the Video → Fal tab (fill in either one) and is created at",
"MiniMax H3 Max(Fal 托管;H3 后训练版,提示遵循更强)": "MiniMax H3 Max (hosted on Fal; post-trained H3, stronger prompt adherence)",
"MiniMax H3 Max Turbo(Fal 托管;速度优先版,仅文生/首尾帧,480P/768P,不支持参考素材)": "MiniMax H3 Max Turbo (hosted on Fal; speed-first variant, text / first-last frame only, 480P/768P, no reference assets)",
"Kling 3.0 Pro(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Pro (hosted on Fal; first/last frame, 3–15 s, native audio, no reference assets)",
"Kling 3.0 Standard(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Standard (hosted on Fal; first/last frame, 3–15 s, native audio, no reference assets)",
"Fal 视频生成 API(queue.fal.run 异步队列,托管 Seedance 2.0/2.5、MiniMax H3、Kling 3.0、Wan 3.0 等端点);模型 ID 填家族前缀,按输入自动补 text-to-video / image-to-video / reference-to-video 任务段,「自定义…」也可填完整端点 ID;分辨率/时长/参考素材上限随所选模型(与官方渠道同口径);Key 在": "Fal video generation API (queue.fal.run async queue hosting Seedance 2.0/2.5, MiniMax H3, Kling 3.0, Wan 3.0 and more); the model ID is the family prefix and the text-to-video / image-to-video / reference-to-video task segment is appended automatically from the inputs, or pick “Custom…” to enter a full endpoint ID; resolution/duration/reference caps follow the selected model (same rules as the official channels); create the Key in the",
"fal.ai 控制台「API Keys」": "fal.ai dashboard “API Keys”",
"直播": "Live",
