"导演模式按秒计费(最少 60 秒),单会话默认最长 2 分钟(更长需向 fal 申请);关闭页面即结束": "Director mode bills per second (60 s minimum); a session is capped at 2 minutes by default (longer needs fal approval); closing the page ends it",
