"播放策略:按顺序播放已生成的片段;新片段还没到时重播最新一段,到了就在当前段结束后接上,不会打断正在播的画面。生成通常慢于播放,所以\"回放\"是常态——把单段时长调长可以减少重播占比。待播片段达到上限(默认 3 段,高级选项可调)时暂停生成,播掉一段再继续。停止后循环回放全部片段。": "Playback: generated clips play in order; while the next clip is not ready the latest one replays, and a new clip is appended after the current one ends without interrupting it. Generation is usually slower than playback, so replaying is normal — longer clips reduce the replay share. Generation pauses when the unplayed cap (default 3, adjustable in Advanced) is reached and resumes once one is played. After stop, all clips loop.",
