"插黑 / 定格": "Black / freeze",
"把选中的时间段直接删掉,剩下的内容按原顺序拼成本组新版本(时长变短,出成片时外挂声轨/字幕按时间映射表自动同步)": "Remove the marked ranges outright and join what remains, in order, into a new version of this group (runtime shrinks; when the episode is finalized the external audio and subtitles are re-synced through the time map)",
"控制切换节奏:在当前时刻插入「前一帧定格 + 黑场」生成本组新版本;或放在本组开头 / 结尾的组边界,写成组间转场处方(提交即回写 shot_list,出成片时插帧)。成片按插入量变长,外挂声轨与字幕按同一张时间映射表自动平移;黑场声音可延续前段、淡出或静音": "Pacing control: insert a \"freeze of the previous frame + black\" at the playhead to build a new version of this group, or place it on the boundary at the start / end of this group as a group transition recipe (submitting writes it back to shot_list; frames are inserted at finalize). The episode grows by the inserted length; external audio and subtitles shift through the same time map; the sound under black can sustain, fade or mute",
"分镜剪辑,四个模块:① 删段——选中的时间段直接删除,剩余拼成新版本;② 换段——切掉的时间段用本组另一版本同段替代;③ 插黑 / 定格——在当前时刻或组边界插入定格帧 + 黑场控制切换节奏;④ 派单剪辑师——输入指令发给剪辑师工位,产物登记为新版本": "Shot editing, four modules: ① Delete — remove the marked ranges and build a new version from what remains; ② Replace — swap the cut ranges for the same ranges of another version of this group; ③ Black / freeze — insert frozen frames + black at the playhead or on a group boundary to control the pacing of a cut; ④ Send to editor — send an instruction to the editor agent; its output is registered as a new version",
"+{s}s → {r}s": "+{s}s → {r}s",
"{a} → {b} 的组边界:前组尾定格 / 黑场后进入本组(写入本组的组间转场处方)": "Boundary {a} → {b}: freeze the previous group's last frame / hold black, then enter this group (written as this group's transition recipe)",
"{a} → {b} 的组边界:本组尾定格 / 黑场后进入下组(写入下组的组间转场处方)": "Boundary {a} → {b}: freeze this group's last frame / hold black, then enter the next group (written as the next group's transition recipe)",
"以 v{a} 为基准,在 {t} 处插入 {p},生成 {g} 的新版本?": "Use v{a} as base, insert {p} at {t}, and build a new version of {g}?",
"入口垫片:": "Entry pad: ",
"入场": "Entry",
"写入中…": "Writing…",
"写入失败:{e}": "Write failed: {e}",
"写入转场处方(草稿)": "Write transition recipe (draft)",
"写入转场处方并提交": "Write transition recipe and submit",
"前一帧(边界 = 前组末帧)冻结的帧数,24fps;0 = 不定格": "Frames to freeze the previous frame (on a boundary: the previous group's last frame), 24 fps; 0 = no freeze",
"在 A 的当前播放时刻插入,生成本组新版本": "Insert at A's current playhead and build a new version of this group",
"基准 v{v} 已含 {n} 处时长编辑,新插入将叠加": "Base v{v} already holds {n} timing edit(s); the new insert stacks on top",
"定格": "Freeze",
"定格 {s}s": "Freeze {s}s",
