"已写入 {g} 的组间转场草稿": "Transition draft for {g} written",
"已回写 shot_list.transition_in({s});出成片时按此插帧,声轨/字幕自动平移": "Written back to shot_list.transition_in ({s}); frames are inserted at finalize and audio/subtitles shift automatically",
"已有未提交的转场草稿,将被替换": "An unsubmitted transition draft exists and will be replaced",
"帧 = {s}s": "frames = {s}s",
"延续": "Sustain",
"延续(循环前一秒,有对白自动改淡出)": "Sustain (loop the previous second; switches to fade if dialogue is near)",
"插入并生成新版本": "Insert and build new version",
"插黑失败:{e}": "Insert failed: {e}",
"本组开头": "Group start",
"本组是末组,没有下组": "This is the last group; there is no next group",
"本组是首组,没有前组": "This is the first group; there is no previous group",
"本组结尾": "Group end",
"淡出": "Fade",
"淡出(150ms 淡至静音,下段淡入)": "Fade (150 ms fade to silence, next part fades in)",
"淡出到黑(前组淡出 → 黑场 → 硬入)": "Fade to black (previous fades out → black → hard in)",
"硬切": "Hard cut",
"穿黑": "Dip to black",
"穿黑(前组淡出 → 黑场 → 本组淡入)": "Dip to black (previous fades out → black → this group fades in)",
"立即提交": "Submit now",
"纯黑帧数,24fps;控节奏常用 6–24 帧,超过 1 秒观众会当成故障": "Frames of pure black, 24 fps; 6–24 frames is typical for pacing, over 1 s reads as a fault",
