"草稿在右侧「包装 › 组间转场(入)」,点「提交」生效": "The draft is under \"Packaging › Group transition (in)\" on the right; click \"Submit\" to apply",
"超过 1 秒的黑场易被当成故障": "Black longer than 1 s tends to read as a fault",
"边界 {a} → {b} 现状:{s}": "Boundary {a} → {b} currently: {s}",
"静音": "Mute",
